// File: counter_scoreboard.sv
// Description: Reference model and checker for the 4-bit up/down counter.
//              Independently computes expected dout and compares with actual.

class counter_scoreboard extends uvm_scoreboard;
  `uvm_component_utils(counter_scoreboard)

  uvm_analysis_imp #(counter_seq_item, counter_scoreboard) ap_imp;

  // Reference model state
  logic [3:0] expected_dout;
  bit         first_txn;
  int         match_count;
  int         mismatch_count;

  // Previous inputs for reference model (to compute expected value)
  bit         prev_rst;
  bit         prev_up;
  bit         prev_valid;  // indicates whether previous inputs are valid

  function new(string name = "counter_scoreboard", uvm_component parent = null);
    super.new(name, parent);
    expected_dout  = 4'h0;
    first_txn      = 1;
    match_count    = 0;
    mismatch_count = 0;
    prev_valid     = 0;
  endfunction

  function void build_phase(uvm_phase phase);
    super.build_phase(phase);
    ap_imp = new("ap_imp", this);
  endfunction

  // The monitor samples the current cycle's rst, up, and dout.
  // The reference model uses the PREVIOUS cycle's rst/up to predict the
  // CURRENT cycle's dout (since the counter is registered).
  function void write(counter_seq_item item);
    if (prev_valid) begin
      // Compute expected dout based on previous cycle's inputs
      if (prev_rst) begin
        expected_dout = 4'h0;
      end else if (prev_up) begin
        expected_dout = expected_dout + 4'd1;
      end else begin
        expected_dout = expected_dout - 4'd1;
      end

      // Compare
      if (item.dout === expected_dout) begin
        match_count++;
        `uvm_info("SCB", $sformatf("PASS: dout=%0h (expected %0h) | prev_rst=%0b prev_up=%0b",
                  item.dout, expected_dout, prev_rst, prev_up), UVM_HIGH)
      end else begin
        mismatch_count++;
        `uvm_error("SCB", $sformatf("MISMATCH: dout=%0h, expected=%0h | prev_rst=%0b prev_up=%0b",
                   item.dout, expected_dout, prev_rst, prev_up))
      end
    end else begin
      // First transaction: capture initial dout, no comparison yet
      expected_dout = item.dout;
      `uvm_info("SCB", $sformatf("Initial dout captured: %0h", item.dout), UVM_MEDIUM)
    end

    // Store current inputs for next cycle's prediction
    prev_rst   = item.rst;
    prev_up    = item.up;
    prev_valid = 1;
  endfunction

  function void report_phase(uvm_phase phase);
    super.report_phase(phase);
    `uvm_info("SCB", $sformatf("===== Scoreboard Summary ====="), UVM_LOW)
    `uvm_info("SCB", $sformatf("  Matches:    %0d", match_count), UVM_LOW)
    `uvm_info("SCB", $sformatf("  Mismatches: %0d", mismatch_count), UVM_LOW)
    `uvm_info("SCB", $sformatf("=============================="), UVM_LOW)
    if (mismatch_count > 0)
      `uvm_error("SCB", $sformatf("TEST FAILED with %0d mismatches", mismatch_count))
    else
      `uvm_info("SCB", "TEST PASSED — all checks matched", UVM_LOW)
  endfunction

