// File: counter_coverage.sv
// Description: Functional coverage subscriber for the 4-bit up/down counter

class counter_coverage extends uvm_subscriber #(counter_seq_item);
  `uvm_component_utils(counter_coverage)

  // Transaction fields for sampling
  bit        rst;
  bit        up;
  logic [3:0] dout;

  // Covergroup definition
  covergroup cg_counter @(cg_sample_event);

    // Coverpoint: reset signal
    cp_rst: coverpoint rst {
      bins active   = {1};
      bins inactive = {0};
    }

    // Coverpoint: up/down direction
    cp_up: coverpoint up {
      bins count_up   = {1};
      bins count_down = {0};
    }

    // Coverpoint: all output values
    cp_dout: coverpoint dout {
      bins zero    = {4'h0};
      bins low     = {[4'h1:4'h3]};
      bins mid_low = {[4'h4:4'h7]};
      bins mid_hi  = {[4'h8:4'hB]};
      bins high    = {[4'hC:4'hE]};
      bins max     = {4'hF};
    }

    // Coverpoint: boundary values for wrap detection
    cp_dout_boundary: coverpoint dout {
      bins val_0  = {4'h0};
      bins val_1  = {4'h1};
      bins val_14 = {4'hE};
      bins val_15 = {4'hF};
    }

    // Cross coverage: direction × output value
    cx_up_dout: cross cp_up, cp_dout {
      // Interesting: counting up at max, counting down at zero
    }

    // Cross coverage: reset × direction
    cx_rst_up: cross cp_rst, cp_up;

    // Cross coverage: direction × boundary values (for wrap scenarios)
    cx_up_boundary: cross cp_up, cp_dout_boundary;

  endgroup

  // Event to trigger covergroup sampling
  event cg_sample_event;

  function new(string name = "counter_coverage", uvm_component parent = null);
    super.new(name, parent);
    cg_counter = new();
  endfunction

  // Called by analysis port when monitor broadcasts a transaction
  function void write(counter_seq_item t);
    rst  = t.rst;
    up   = t.up;
    dout = t.dout;
    -> cg_sample_event;
  endfunction

  function void report_phase(uvm_phase phase);
    super.report_phase(phase);
    `uvm_info("COV", $sformatf("Functional Coverage: %.2f%%", cg_counter.get_coverage()), UVM_LOW)
  endfunction

endclass : counter_coverage

