// File: tb_top.sv
// Description: Top-level testbench module. Instantiates clock generator,
//              DUT, interface, and launches UVM test.

module tb_top;



  // -------------------------------------------------------------------------
  // Clock generation: 10ns period (100 MHz)
  // -------------------------------------------------------------------------
  logic clk;
  initial begin
    clk = 0;
    forever #5 clk = ~clk;
  end

  // -------------------------------------------------------------------------
  // Interface instantiation (using the provided counter_if)
  // -------------------------------------------------------------------------
  counter_if cif(.clk(clk));

  // -------------------------------------------------------------------------
  // DUT instantiation
  // -------------------------------------------------------------------------
  counter dut (
    .clk  (clk),
    .rst  (cif.rst),
    .up   (cif.up),
    .dout (cif.dout)
  );

  // -------------------------------------------------------------------------
  // Store virtual interface handles in config_db
  // -------------------------------------------------------------------------
  initial begin
    uvm_config_db #(virtual counter_if.DRV)::set(null, "uvm_test_top.env.agent.drv", "vif_drv", cif.DRV);
    uvm_config_db #(virtual counter_if.MON)::set(null, "uvm_test_top.env.agent.mon", "vif_mon", cif.MON);
  end

  // -------------------------------------------------------------------------
  // Launch UVM test
  // -------------------------------------------------------------------------
  initial begin
    run_test("counter_base_test");
  end

  // -------------------------------------------------------------------------
  // Simulation timeout and waveform dump
  // -------------------------------------------------------------------------
  initial begin
    $timeformat(-9, 2, " ns", 12);
    #100_000;
    `uvm_fatal("TIMEOUT", "Simulation timed out after 100us")
  end

  initial begin
    $dumpfile("counter_tb.vcd");
    $dumpvars(0, tb_top);
  end

endmodule : tb_top

